package org.beyondlight;

import java.time.Instant;
import java.util.*;

/** Bounded symbolic feature-structure search with deterministic cross-validation. */
public final class AutonomousModelExplorer {
 private record Feature(String expression,String kind,List<String> columns,double[] values){Map<String,Object> json(){return Map.of("expression",expression,"kind",kind,"columns",columns);}}
 private AutonomousModelExplorer(){}
 public static Map<String,Object> explore(DataRepository.Dataset d,String target){
  List<String> names;List<List<String>> rows;if(d.format().equals("csv")){List<List<String>> t=DataRepository.csv(d.raw());names=t.get(0);rows=t.subList(1,t.size());}else{Map<String,Object> o=Json.map(Json.parse(d.raw()));names=strings(o.get("variables"));rows=new ArrayList<>();for(Object r:(List<?>)o.get("rows"))rows.add(strings(r));}
  int yi=names.indexOf(target);if(yi<0||rows.size()<6)throw new IllegalArgumentException("target column and at least six rows required");int n=Math.min(2000,rows.size());int[] index=new int[n];double[] y=new double[n];for(int i=0;i<n;i++){index[i]=n==rows.size()?i:(int)((long)i*(rows.size()-1)/(n-1));y[i]=Double.parseDouble(rows.get(index[i]).get(yi));if(!Double.isFinite(y[i]))throw new IllegalArgumentException("target contains nonfinite data");}
  Map<String,double[]> columns=new LinkedHashMap<>();for(int c=0;c<names.size();c++)if(c!=yi){double[] v=new double[n];for(int i=0;i<n;i++){v[i]=Double.parseDouble(rows.get(index[i]).get(c));if(!Double.isFinite(v[i]))throw new IllegalArgumentException("input contains nonfinite data");}if(variance(v)>1e-24)columns.put(names.get(c),v);}
  List<Map.Entry<String,double[]>> selected=columns.entrySet().stream().sorted(Comparator.comparingDouble((Map.Entry<String,double[]> e)->-Math.abs(correlation(e.getValue(),y)))).limit(4).toList();List<Feature> features=new ArrayList<>();Map<String,double[]> zcols=new LinkedHashMap<>();for(var col:selected){double mean=Arrays.stream(col.getValue()).average().orElse(0),sd=Math.sqrt(variance(col.getValue()));double[] z=new double[n];for(int i=0;i<n;i++)z[i]=(col.getValue()[i]-mean)/sd;zcols.put(col.getKey(),z);String zn="z("+col.getKey()+")";features.add(new Feature(zn,"linear",List.of(col.getKey()),z));features.add(new Feature(zn+"^2","square",List.of(col.getKey()),map(z,v->v*v)));features.add(new Feature("exp(clamp("+zn+"))","exponential",List.of(col.getKey()),map(z,v->Math.exp(Math.max(-5,Math.min(5,v))))));features.add(new Feature("ln(1+abs("+zn+"))","log_abs",List.of(col.getKey()),map(z,v->Math.log1p(Math.abs(v)))));}
  List<String> predictorNames=new ArrayList<>(zcols.keySet());Map<String,List<Double>> normalization=new LinkedHashMap<>();for(var col:selected){double mean=Arrays.stream(col.getValue()).average().orElse(0),sd=Math.sqrt(variance(col.getValue()));normalization.put(col.getKey(),List.of(mean,sd));}for(int a=0;a<predictorNames.size();a++)for(int b=a+1;b<predictorNames.size();b++){String x=predictorNames.get(a),z=predictorNames.get(b);double[] xv=zcols.get(x),zv=zcols.get(z),v=new double[n];for(int i=0;i<n;i++)v[i]=xv[i]*zv[i];features.add(new Feature("z("+x+")*z("+z+")","interaction",List.of(x,z),v));}
  int folds=Math.min(5,n/3);List<Map<String,Object>> models=new ArrayList<>();for(int a=0;a<features.size();a++)for(int b=-1;b<a;b++){int[] selectedFeatures=b<0?new int[]{a}:new int[]{b,a};double[] full=fit(features,selectedFeatures,y,null,0);if(full==null)continue;double cv=0,base=0;int count=0;boolean valid=true;for(int f=0;f<folds;f++){double[] p=fit(features,selectedFeatures,y,f,folds);if(p==null){valid=false;break;}double mean=0;int train=0;for(int i=0;i<n;i++)if(i%folds!=f){mean+=y[i];train++;}mean/=train;for(int i=0;i<n;i++)if(i%folds==f){double pred=p[0];for(int k=0;k<selectedFeatures.length;k++)pred+=p[k+1]*features.get(selectedFeatures[k]).values()[i];cv+=sq(y[i]-pred);base+=sq(y[i]-mean);count++;}}if(!valid||count==0)continue;double sse=0,ym=Arrays.stream(y).average().orElse(0),sst=0;for(int i=0;i<n;i++){double pred=full[0];for(int k=0;k<selectedFeatures.length;k++)pred+=full[k+1]*features.get(selectedFeatures[k]).values()[i];sse+=sq(y[i]-pred);sst+=sq(y[i]-ym);}List<String> terms=new ArrayList<>();List<Map<String,Object>> definitions=new ArrayList<>();for(int k:selectedFeatures){terms.add(features.get(k).expression());definitions.add(features.get(k).json());}String equation="y = "+full[0];for(int k=0;k<terms.size();k++)equation+=" + ("+full[k+1]+")*"+terms.get(k);Map<String,Object> model=new LinkedHashMap<>();model.put("equation",equation.replaceFirst("^y",target));model.put("terms",terms);model.put("termDefinitions",definitions);model.put("coefficients",Arrays.stream(full).boxed().toList());model.put("fitRmse",Math.sqrt(sse/n));model.put("crossValidationRmse",Math.sqrt(cv/count));model.put("trainingMeanBaselineRmse",Math.sqrt(base/count));model.put("rSquared",sst==0?null:1-sse/sst);model.put("beatsInternalBaseline",cv<base);model.put("coefficientUnit",unitFor(d.units(),target));model.put("classification",cv<base?"UNVERIFIED_CANDIDATE_SUPPORTED_WITHIN_DATASET":"UNVERIFIED_CANDIDATE_NOT_SUPPORTED_BY_INTERNAL_CV");models.add(model);}
  models.sort(Comparator.comparingDouble(m->((Number)m.get("crossValidationRmse")).doubleValue()));List<Map<String,Object>> best=models.stream().limit(8).toList();Map<String,Object> out=new LinkedHashMap<>();out.put("id",UUID.randomUUID().toString());out.put("date",Instant.now().toString());out.put("recordType","AUTONOMOUS_MODEL_EXPLORATION");out.put("category","research");out.put("title","Pencarian struktur model otomatis: "+target+" dari "+d.filename());out.put("model","Feature grammar search: linear, quadratic, exponential, logarithmic, pair interactions; one- and two-term combinations");out.put("inputs",Map.of("datasetId",d.id(),"filename",d.filename(),"target",target,"predictorsSearched",predictorNames,"normalization",normalization,"rowsAnalyzed",n,"folds",folds,"featureStructuresGenerated",features.size(),"candidateStructuresFitted",models.size()));out.put("result",Map.of("status",best.stream().anyMatch(m->Boolean.TRUE.equals(m.get("beatsInternalBaseline")))?"CANDIDATE_MODEL_FOUND_INTERNAL_SCREEN_ONLY":"NO_MODEL_PASSED_INTERNAL_SCREEN","bestModels",best));out.put("sources",List.of(Map.of("datasetId",d.id(),"filename",d.filename(),"source",d.source(),"author",d.author(),"year",d.year(),"doi",d.doi(),"datasetStatus",d.status())));out.put("equations",best.stream().map(m->Map.of("equation",m.get("equation"),"classification",m.get("classification"))).toList());out.put("status",best.stream().anyMatch(m->Boolean.TRUE.equals(m.get("beatsInternalBaseline")))?"UNVERIFIED_DATA_DERIVED_MODEL_CANDIDATE":"NO_MODEL_SUPPORTED_BY_INTERNAL_CV");out.put("limitations",List.of("Equation structures are searched from a bounded mathematical feature grammar; this is not autonomous physical theory or law discovery.","Standardized predictors are dimensionless; coefficients inherit target units. This dimensional bookkeeping alone does not prove physical validity.","Cross-validation reuses this dataset. Independent sourced data and experiments are still required."));return out;
 }
 private interface F{double apply(double x);}private static double[]map(double[]a,F f){double[]b=new double[a.length];for(int i=0;i<a.length;i++)b[i]=f.apply(a[i]);return b;}private static double variance(double[]a){double m=Arrays.stream(a).average().orElse(0),s=0;for(double v:a)s+=sq(v-m);return s/a.length;}private static double correlation(double[]x,double[]y){double mx=Arrays.stream(x).average().orElse(0),my=Arrays.stream(y).average().orElse(0),a=0,b=0,c=0;for(int i=0;i<x.length;i++){double u=x[i]-mx,v=y[i]-my;a+=u*v;b+=u*u;c+=v*v;}return b*c==0?0:a/Math.sqrt(b*c);}private static double sq(double x){return x*x;}
 private static double[]fit(List<Feature> fs,int[] terms,double[] y,Integer fold,int folds){int p=terms.length+1;double[][]a=new double[p][p+1];int count=0;for(int i=0;i<y.length;i++)if(fold==null||i%folds!=fold){count++;double[]v=new double[p];v[0]=1;for(int j=0;j<terms.length;j++)v[j+1]=fs.get(terms[j]).values()[i];for(int r=0;r<p;r++){a[r][p]+=v[r]*y[i];for(int c=0;c<p;c++)a[r][c]+=v[r]*v[c];}}if(count<p)return null;for(int i=0;i<p;i++){int pivot=i;for(int r=i+1;r<p;r++)if(Math.abs(a[r][i])>Math.abs(a[pivot][i]))pivot=r;if(Math.abs(a[pivot][i])<1e-12)return null;double[] tmp=a[i];a[i]=a[pivot];a[pivot]=tmp;double d=a[i][i];for(int c=i;c<=p;c++)a[i][c]/=d;for(int r=0;r<p;r++)if(r!=i){d=a[r][i];for(int c=i;c<=p;c++)a[r][c]-=d*a[i][c];}}double[] out=new double[p];for(int i=0;i<p;i++)out[i]=a[i][p];return out;}
 private static String unitFor(String units,String target){for(String pair:units.split(",")){String[]a=pair.trim().split(":",2);if(a.length==2&&a[0].trim().equals(target))return a[1].trim();}return "unknown";}private static List<String>strings(Object o){List<String>a=new ArrayList<>();for(Object v:(List<?>)o)a.add(String.valueOf(v));return a;}
}
